(function(){"use strict";function forceLoadAllImages(){const allImages=document.querySelectorAll("img");allImages.forEach(img=>{if(img.dataset.src&&!img.src){img.src=img.dataset.src}const picture=img.closest("picture");if(picture){const sources=picture.querySelectorAll("source");sources.forEach(source=>{if(source.srcset&&!img.src){const firstSrc=source.srcset.split(" ")[0];if(firstSrc){img.src=firstSrc}}})}img.loading="eager";img.classList.add("force-loaded");img.onerror=function(){console.log("Image failed to load:",this.src);if(this.dataset.fallback){this.src=this.dataset.fallback}};img.onload=function(){this.classList.add("loaded")}})}forceLoadAllImages();if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",forceLoadAllImages)}window.addEventListener("load",forceLoadAllImages);setTimeout(forceLoadAllImages,1e3);setTimeout(forceLoadAllImages,3e3)})();